using System;
using UnityEngine;

namespace Chaos.VectorExtensions;

public static class VectorExtension
{
	public static Vector2 Randomize(this Vector2 vec, float range = 1f, float radius = -1f, float minRadius = 1f)
	{
		if (radius > 0f)
		{
			range = UnityEngine.Random.Range(0f, (float)Math.PI * 2f);
			radius = UnityEngine.Random.Range(minRadius, radius);
			vec.x += Mathf.Cos(range) * radius;
			vec.y += Mathf.Sin(range) * radius;
		}
		else
		{
			vec.x += UnityEngine.Random.Range(0f - range, range);
			vec.y += UnityEngine.Random.Range(0f - range, range);
		}
		return vec;
	}

	public static Vector3 Randomize(this Vector3 vec, float range = 1f, float radius = -1f, float minRadius = 1f)
	{
		return ((Vector2)vec).Randomize(range, radius, minRadius);
