('два','nom'):'две',('два','gen'):'две',('оба','nom'):'обе'}
DETS=set(k[0] for k in SPEC)
ADJ=re.compile(r'^[а-яё]+(?:ый|ий|ой|ое|ее|ого|его|ому|ему|ым|им|ом|ем)$',re.I)
BADADJ={'этом','том','всем','таком','каком','чем','нем','ним','тем','ком','кем','дом','объем','объём','своем','всём','нём','при','любом','целом','общем','новом'}
