        for a,b,c in [('ый','ая','ую'),('ий','яя','юю'),('ой','ая','ую'),('ое','ая','ую'),('ее','яя','юю')]:
            if lw.endswith(a):
                r=lw[:-len(a)]+(b if case=='nom' else c);break
    elif case=='gen':
        for a,b in [('ого','ой'),('его','ей')]:
            if lw.endswith(a):
                r=lw[:-3]+b;break
    elif case=='dat':
        for a,b in [('ому','ой'),('ему','ей')]:
            if lw.endswith(a):
                r=lw[:-3]+b;break
