    return r.capitalize() if w[0].isupper() else r
ACCPREP={'в','на','за','под','через','про'}
NOTVERB={'если','когда','чтобы','пока','или','либо','как','между','перед','после','при','для','от','из','без','что','тем','чем','нет','есть','тип','вид','хит','пустой','ульта','каст','ячейка','пуль','слот'}
VERB=re.compile(r'(ть|ться|ет|ёт|ит|ют|ат|ят|ут|ёшь|ешь|ишь)$')
def process(text,forms,log,fname):
    pat=re.compile(r'(?<![А-Яа-яЁё-])('+'|'.join(sorted(forms,key=len,reverse=True))+r')(?![А-Яа-яЁё])',re.I)
    out=[];last=0
    for m in pat.finditer(text):
        w=m.group(1);lw=w.lower()
        case,new=forms[lw]
        mods=[];pos=m.start();ctx_word=None
        for _ in range(4):
            lo=max(0,pos-40)
            mm=re.search(r'([А-Яа-яЁё-]+) $',text[lo:pos])
            if not mm: break
            wstart=lo+mm.start(1);wend=lo+mm.end(1)
            word=mm.group(1);lwd=word.lower()
            if lwd in DETS or (ADJ.match(lwd) and lwd not in BADADJ):
                mods.append((wstart,wend,word));pos=wstart
            else:
                ctx_word=lwd;break
        c=case
        if case=='nom' and ctx_word and (ctx_word in ACCPREP or (VERB.search(ctx_word) and ctx_word not in NOTVERB)):
            c='acc'
        newword=new.capitalize() if w[0].isupper() else new
        if case=='nom' and c=='acc': newword='Аркану' if w[0].isupper() else 'аркану'
        repl=[]
        for ws_,we_,mw in mods:
            f=fem(mw,c if case=='nom' else case)
            repl.append((ws_,we_,f if f else mw+'!!'))
        repl.sort()
        seg=last
        for ws_,we_,f in repl:
            out.append(text[seg:ws_]);out.append(f);seg=we_
        out.append(text[seg:m.start()]);out.append(newword);last=m.end()
        log.append((fname,text[max(0,m.start()-45):m.end()+22].replace('\n',' '),c,''.join(x for x in (' '+ ' '.join(f for _,_,f in repl)) )))
    out.append(text[last:])
    return ''.join(out)
if __name__=='__main__':
    apply='--apply' in sys.argv
    log=[]
    for f in sorted(glob.glob(S+'*.md')):
        n=f.replace('\\','/').split('/')[-1]
        if n.startswith('10-bosses') or n.startswith('06-enemy') or n.startswith('coverage.csv'): continue
        t=open(f,encoding='utf-8').read();o=t
        L=[]
        t=process(t,PR,L,n)
        t=process(t,UM,L,n)
        log+=L
        if apply and t!=o: open(f,'w',encoding='utf-8',newline='').write(t)
    print(len(log))
    if '--show' in sys.argv:
        for x in log: print(x[0][:7],x[2],'|',x[1],'=>',x[3])

