public class FinalBossHurtState : BossHurtState
{
	private float calcDuration;

	private bool superModeVarsSet;

	public new FinalBoss parent;

	public FinalBossHurtState(string newName, FSM newFSM, FinalBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void SetHurtVars()
	{
		baseHurtDuration = Mathf.Max(0.5f, Mathf.Lerp(0.9f, 0.7f, parent.DifficultyValue) * Boss.BaseHurtDurationMultiplier.CurrentValue);
		maxHurtDuration = baseHurtDuration * 2f;
		stunOverrideValue = baseHurtDuration;
	}

	public override void OnEnter()
	{
		if (parent.superMode && !superModeVarsSet)
		{
			varsSet = true;
			superModeVarsSet = true;
			baseHurtDuration = Mathf.Max(0.38f, Mathf.Lerp(0.65f, 0.5f, parent.DifficultyValue) * Boss.BaseHurtDurationMultiplier.CurrentValue);
			maxHurtDuration = baseHurtDuration * 2f;
			stunOverrideValue = baseHurtDuration;
		}
		animName = ((!parent.chaosMode) ? "Hurt" : "HurtHoodless");
		parent.AllowKnockback(status: true);
		base.OnEnter();
	}

	public override void OnExit()
	{
		if (!parent.fsm.nextStateName.Contains("Hurt"))
		{
			hitCounter = 0;
			parent.AllowHurtState(parent.chaosMode);
			parent.AllowKnockback(status: false);
			if (stunEffect != null)
			{
				stunEffect.Stop(playRecoveryFX: true);
				stunEffect = null;
			}
		}
	}

	public override void ExitTransition()
	{
		if (parent.chaosMode)
		{
			SpawnPortal poolItem = PoolManager.GetPoolItem<SpawnPortal>();
			poolItem.Spawn(parent.transform.position, SpawnPortal.enemyColor);
			poolItem.Spawn(parent.stageCenter, SpawnPortal.enemyColor);
			parent.transform.position = parent.stageCenter;
			parent.fsm.ChangeState(parent.chaosShieldState.name, allowSelfTransition: true);
			parent.rigidbody2D.velocity = Vector2.zero;
		}
		else
		{
			base.ExitTransition();
		}
	}

	public override void HandleDurationIncrease(bool first = false)
	{
		if (first)
		{
			hitCounter = 1;
			hurtStopwatchID = ChaosStopwatch.Begin((!parent.chaosMode) ? baseHurtDuration : maxHurtDuration);
			return;
		}
		if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
		{
			hitCounter++;
		}
		hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
	}
}

