bad=0
for f in ['05c-arcana-full.md','15b-relics-catalog.md','05b-arcana-catalog.md']:
    prev=None
    for i,l in enumerate(open(f,encoding='utf-8'),1):
        if l.startswith('|'):
            n=l.count('|')
